'use strict';
const F=Forge,D=F.D,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>'Cr'+fmt(n),band=n=>D.SpeedBand.find(x=>x['Speed Band']===n)?.['Speed Band Name']||'Stopped';
const U=VehicleUI,systemGroups=U.groups(F.options),systemPicks={},systemQuantities={},systemConfigs={};
let state=structuredClone(F.defaults),tab='chassis',filter='',group='All',result;
const tabs=[['chassis','Chassis'],['features','Features'],['power','Power & mobility'],['armour','Armour & hull'],['equipment','Core systems'],['external','External options'],['internal','Internal options'],['automation','Computers & automation'],['weapons','Weapon mounts'],['crew','Crew & cargo'],['record','Record & checks']];
const sourceIndex=Object.fromEntries([...Object.values(D).flat(),...F.options].filter(x=>x._source).map(x=>[x._source,x]));
function ref(o,p){if(typeof o==='string'){const matching=Object.values(sourceIndex).find(x=>o.includes(x._source));if(matching&&!o.startsWith('Handbook'))return ref(matching);return `<span class="ref">Vehicle Handbook Update 2026${p?', pp. '+esc(p):': '+esc(o.replace(/^Handbook /,''))}</span>`}return `<span class="ref">${o?._book?esc(o._book)+' · pp. '+esc(o._pages):'Book page not verified'}${o?._handbookOnly?'':`<br><span class="cell">Vehicle Design Worksheet v0.56 · ${esc(o?._source||'')}</span>`}</span>`}
const bh=(p)=>`<span class="ref">Vehicle Handbook Update 2026 · pp. ${p}</span>`;
const field=(label,key,type='number',extra='',help='')=>`<label class="field">${label}<input type="${type}" data-key="${key}" value="${esc(state[key])}" ${extra}>${help?`<small>${help}</small>`:''}</label>`;
const select=(label,key,items,help='')=>`<label class="field">${label}<select data-key="${key}">${items.map(x=>{const v=Array.isArray(x)?x[0]:x,l=Array.isArray(x)?x[1]:x;return `<option value="${esc(v)}" ${state[key]===v?'selected':''}>${esc(l)}</option>`}).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;
const check=(label,key)=>`<label class="inline"><input type="checkbox" data-key="${key}" ${state[key]?'checked':''}>${label}</label>`;
const panel=(n,title,body,subtitle='')=>`<div class="panel"><div class="panelhead"><h2><span class="number">${n}</span>${title}</h2><small>${subtitle}</small></div>${body}</div>`;
const rule=(text,page)=>`<div class="rule">${text}${bh(page)}</div>`;
function render(){
 const openCategories=[...document.querySelectorAll('.system-category[open]')].map(el=>el.querySelector('summary').firstChild.textContent);
 result=F.calculate(state);
 if(!$('#nav').children.length||$('#nav').dataset.active!==tab){$('#nav').dataset.active=tab;$('#nav').innerHTML=tabs.map(([id,name],i)=>`<button data-tab="${id}" class="${id===tab?'active':''}" aria-current="${id===tab?'step':'false'}"><b>${String(i+1).padStart(2,'0')}</b>${name}</button>`).join('');}
 $('#vehicle-name').value=state.name;$('#subtitle').textContent=`${result.size?.['Size Name']||''} ${state.type.toLowerCase()} · TL${state.tl} · ${fmt(state.spaces)} nominal Spaces`;
 $('#editor').innerHTML=views[tab]();renderSummary();
 if(['equipment','external','internal','automation'].includes(tab))for(const el of document.querySelectorAll('.system-category'))if(openCategories.includes(el.querySelector('summary').firstChild.textContent))el.open=true;
}
const views={
chassis(){return panel('01','Start with the chassis',`<div class="body"><div class="grid">${select('Vehicle type','type',F.types.map(x=>[x.Type,`${x.Type} · TL${x.TL}+`]))}${field('Tech Level','tl','number','min="0" max="20" step="1"','All components are checked against this TL.')}${field('Nominal Spaces','spaces','number','min="1" max="1000000" step="1"','Determines size, cost, shipping and equipment budgets.')}<div><label>Size classification</label><div class="statchips"><span><b>${result.size['Size Name']}</b></span><span>${fmt(result.shipping)} shipping tons</span></div>${bh('25–26')}</div></div><div class="statchips"><span>Baseline <b>${money(result.t.Cost)} / Space</b></span><span>Hull <b>${result.t.Hull} / Space</b></span><span>Skill <b>${esc(result.t.Skill)}</b></span></div>${rule('The nominal chassis size stays fixed when power systems or customisations increase usable capacity. A structure starts with twice its nominal Spaces.','25–27')}${state.type==='Airship'?`<div class="grid" style="margin-top:20px">${select('Lifting gas','gas',['Hot Air','Helium','Hydrogen','Vacuum'])}</div>${rule('Only the gas envelope’s available fraction may be fitted out. Vacuum lift requires Rigid. Gas TL limits are enforced.','29')}`:''}${state.type==='Submersible'?`<div style="margin-top:20px">${field('Depth multiplier','depth','number','min="1" step="1"','Each additional multiplier adds 100% baseline cost and +1 base armour.')}</div>`:''}</div>`,'10 vehicle types')+panel('↳','Starting designs',`<div class="body"><p class="muted">Load a fresh configuration to explore the rules. This replaces the current draft.</p><div class="preset"><button data-preset="rover">Utility rover · TL9</button><button data-preset="raft">Air/raft · TL12</button><button data-preset="blank">Empty chassis</button></div></div>`)+panel('≡','Type baseline',`<div class="tablewrap"><table><thead><tr><th>Type</th><th>TL</th><th>Cr / Space</th><th>Book & page</th></tr></thead><tbody>${F.types.map(x=>`<tr><td>${esc(x.Type)}</td><td>${x.TL}</td><td>${fmt(x.Cost)}</td><td>${ref(x)}</td></tr>`).join('')}</tbody></table></div>`);},
features(){const available=U.availableFeatures(F,state),unavailable=U.unavailableSelected(F,state);return panel('02','Available construction features',`<div class="body"><p class="muted">Only features allowed by this chassis, TL, size, power and current selections are shown. Choose prerequisites first to unlock dependent features.</p>${unavailable.length?`<div class="issue"><b>SELECTED FEATURES NEED ATTENTION</b>${unavailable.map(name=>`<div class="feature-conflict"><span><strong>${esc(name)}</strong><br>${esc(F.featureReasons(name,state).join(' · '))}</span><button data-remove-feature="${esc(name)}" class="small danger">Remove ${esc(name)}</button></div>`).join('')}</div>`:''}<div class="featuregrid">${available.map(f=>{const name=f['Feature Effect'],selected=state.features.includes(name);return `<div class="feature ${selected?'selected':''}"><label><input type="checkbox" data-feature="${esc(name)}" ${selected?'checked':''}>${esc(name)} <span class="chip">TL${f.TL}</span></label><p>${esc(f.Effect)}</p><span class="chip orange">${f['Cost add']>=0?'+':''}${roundPercent(f['Cost add'])}% base cost</span>${ref(f)}</div>`}).join('')}</div>${!available.length?'<div class="empty">No construction features are available for this configuration.</div>':''}${rule('Feature price changes add against the original chassis cost. AFV and Tracks share one speed penalty. Biotech construction is outside this conventional-vehicle workbench.','35–43, 131–136')}</div>`,`${available.length} available`);},
power(){return panel('03','Power systems',`<div class="body"><div class="grid">${select('Primary power','power',F.powers.map(p=>[p.Power,`${p.Power} · TL${p.TL}+`]))}${select('Secondary power','secondary',['none',...F.powers.map(p=>p.Power)])}${field('Extra primary reactor Spaces','extraPower','number','min="0" step="1"','Requires a nuclear primary power system.')}${state.type==='Structure'?select('Powered structure ruling','ruling',[['table','30% · p45 table / workbook'],['prose','25% · p32 prose']]):`<div><label>Reactor output</label><div class="statchips"><span><b>${fmt(result.pp)}</b> Power</span></div>${bh('44–48')}</div>`}</div>${rule('Installed plant Spaces round up and respect plant minimums. Unpowered vehicles cannot carry secondary power; structures can. Fission needs hostile environment protection.','44–48')}</div>`)+panel('↳','Performance customisations',`<div class="body"><div class="grid three">${field('Speed steps','speedMod','number','min="-3" max="3" step="1"','−3 to +3; TL4/5/6 unlocks 1/2/3 steps.')}${field('Fuel efficiency steps','efficiency','number','min="-3" max="3" step="1"','+50% or −25% range per step.')}${field('Fuel capacity steps','fuel','number','min="-2" max="100" step="1"','+25% or −25% range per step; two reductions maximum.')}</div>${rule('Each Faster step consumes ceil(20% × nominal Spaces); Slower gains floor(10%). Fuel steps use 10% per step. Efficiency and fuel percentages add after other range modifiers.','49–50')}</div>`)+panel('↳','Auxiliary locomotion',`<div class="body"><div class="grid">${[0,1].map(i=>`<label class="field">${i?'Tertiary':'Secondary'} drive<select data-aux="${i}"><option value="none">None</option>${D.Secondary.filter(a=>a.TL!==null&&a.Secondary!=='none').map(a=>`<option value="${esc(a.Secondary)}" ${state.aux[i]===a.Secondary?'selected':''}>${esc(a.Secondary)} · TL${a.TL}+</option>`).join('')}</select></label>`).join('')}</div>${state.features.includes('Rail Rider')?`<div class="grid" style="margin-top:20px">${select('Rail network','rail',D.RailNetwork.map(r=>r['Rail Network']))}${check('Vacc tube network','vacTube')}</div>`:''}${rule('Auxiliary performance uses the equivalent standard vehicle. Primary features and customisations do not boost the auxiliary drive. Rocket entries install one round of thrust and require trajectory review.','50–54')}${result.auxResults.length?`<div class="tablewrap"><table><thead><tr><th>Drive</th><th>Speed</th><th>Range</th><th>Book & page</th></tr></thead><tbody>${result.auxResults.map(a=>`<tr><td>${esc(a.name)}</td><td>${band(a.speed)}</td><td>${fmt(a.range)} km</td><td>${ref(D.Secondary.find(x=>x.Secondary===a.name))}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`);},
armour(){return panel('04','Protection & structure',`<div class="body"><div class="grid">${field('Added overall armour','armour','number','min="0" step="1"',`Base ${result.baseArmour}; total limit ${result.maxArmour}.`)}${select('Hull construction','hull',['Standard','Reinforced','Light'])}</div><div class="statchips"><span>Armour volume <b>${result.armourSpaces} Spaces</b></span><span>Hull <b>${fmt(result.hull)}</b></span><span>Structure <b>${result.structure}</b></span></div>${rule('Structure is one-tenth of Hull, rounded up.','6')}${rule('The four side faces receive full added armour; dorsal and ventral receive half, rounded up. Enter transfers below: additions and removals must sum to zero. Each face keeps its base armour, except an open top.','26, 55–56')}<div class="armour-grid">${F.faces.map((face,i)=>`<div class="armourcell"><span>${face}</span><b>${result.protection[i]}</b><small class="muted">${result.protection[i]+(result.protection[i]>=result.baseArmour?state.tl:0)} vs small arms</small><label>Transfer<input type="number" data-armour="${i}" step="1" value="${state.armourShift[i]}" aria-label="${face} armour transfer"></label></div>`).join('')}</div></div>`)+panel('≡','Armour materials',`<div class="tablewrap"><table><thead><tr><th>TL</th><th>Material</th><th>Base / Max</th><th>Spaces / point</th><th>Book & page</th></tr></thead><tbody>${D.Armour.filter((x,i)=>!i||D.Armour[i-1].Base!==x.Base).map(x=>`<tr><td>${x.TL}+</td><td>${esc(x.Materials)}</td><td>${x.Base} / ${x.Max}</td><td>${fmt(x['Vehicle Spaces per Point']*100)}%</td><td>${ref(x)}</td></tr>`).join('')}</tbody></table></div>`);},
equipment(){const scope=['equipment','external','internal','automation'].includes(tab)?tab:'equipment';const titles={equipment:'Core systems',external:'External options & defence',internal:'Internal options & facilities',automation:'Computers & automation'};const cats=['Core systems','Automation','Exterior','Defence','Interior & comfort','Utility','Specialist & spacecraft'];const matches=systemGroups.filter(g=>(filter||U.section(g.options[0],F)===scope)&&g.options.some(o=>(group==='All'||F.category(o)===group)&&U.searchText(g).includes(filter.toLowerCase().replaceAll('-',' '))));return panel(String(tabs.findIndex(x=>x[0]===tab)+1).padStart(2,'0'),titles[scope],`<div class="body">${scope==='equipment'?select('Control system','control',F.options.filter(x=>x.Name.startsWith('Control System')&&(x.TL<=state.tl||x.Name===state.control)).map(x=>[x.Name,`${x.Name} · TL${x.TL}+ · ${money(x.CostU)}`]))+field('Control stations','controlQuantity','number','min="1" step="1"')+rule('Basic controls are included. Better control systems require power and increase Agility.','58'):''}<div class="quick-equipment"><button data-equipment-search="life support">Life support</button><button data-equipment-search="tow cable">Towing & cables</button><button data-equipment-search="transceiver">Transceivers & upgrades</button><button data-equipment-search="bay">Bays</button><button data-equipment-search="">All equipment</button></div><div class="catalogtools system-search"><input id="equipment-search" type="search" value="${esc(filter)}" placeholder="Find a system…" aria-label="Search equipment"><select id="equipment-group" aria-label="Equipment category">${['All',...cats].map(g=>`<option ${group===g?'selected':''}>${g}</option>`).join('')}</select></div><p class="muted">Choose an option in each system dropdown, then install it. Notes, cost and Spaces update with your choice. Quantities can be changed below.</p></div>`)+panel('↳','Other equipment locations',`<div class="body"><p class="muted">Anti-missile systems are selected as weapons with their mount. Custom robot brains and items without defined construction values are listed in the source audit.</p><button data-tab="weapons">Weapon mounts & anti-missile systems →</button></div>`)+cats.map(cat=>{const groups=matches.filter(g=>F.category(g.options[0])===cat);return groups.length?`<details class="panel system-category" ${group!=='All'||filter||groups.length<25?'open':''}><summary>${cat}<span>${groups.length} system types</span></summary><div class="body system-grid">${groups.map(systemCard).join('')}</div></details>`:''}).join('')+(!matches.length?'<div class="empty">No systems match your search.</div>':'')+panel('↳','Installed equipment · all sections',equipmentTable());},
external(){return views.equipment();},
internal(){return views.equipment();},
automation(){return views.equipment();},
weapons(){return panel('09','Weapon mounts',`<div class="body"><p class="muted">Choose identical linked weapons per mount. Turret crew occupy mount Spaces; remote crew use the accommodation allocation.</p><div class="spaced"><span class="chip">${fmt(result.weaponMass)} / ${fmt(state.spaces*250)} kg hard limit</span><button data-action="add-weapon" class="primary">＋ Add mount</button></div>${rule('Above 100 kg of weapons per nominal Space, speed drops one band. Above 250 kg per Space, the design is invalid. Hardpoint weapons count toward both thresholds.','101')}</div>`)+state.weapons.map((w,i)=>`<div class="panel"><div class="body"><div class="spaced"><h3>Mount ${String(i+1).padStart(2,'0')}</h3><button class="danger small" data-remove-weapon="${i}">Remove</button></div><div class="grid"><label class="field wide">Weapon<select data-weapon="${i}" data-prop="weapon">${F.weapons.filter(x=>x.TL<=state.tl||x.Weapon===w.weapon).map(x=>`<option value="${esc(x.Weapon)}" ${w.weapon===x.Weapon?'selected':''}>${esc(x.Weapon)} · TL${x.TL} · ${fmt(x.Tons*1000)} kg</option>`).join('')}</select></label>${w.weapon.startsWith('Anti-Missile System')?'<div class="rule">Self-contained automated turret: mount, sensors and fire control included. Vehicle Handbook Update 2026 · pp. 73–74.</div>':weaponSelect(i,'Mount','mount',['Fixed Mount','Hardpoint','Pintle Mount','Ring Mount','Gunport','Bay','Multi-Bay','Turret'])}${w.weapon==='No weapon installed'?weaponNumber(i,'Rated weapon Spaces','ratedSpaces',1)+weaponNumber(i,'Reserved turret crew','reservedCrew',0):''}${weaponSelect(i,'Facing','facing',F.faces)}${weaponNumber(i,'Identical linked weapons','quantity',1)}${weaponSelect(i,'Fire control','fireControl',['none','Scope','Basic','Improved','Enhanced','Advanced'])}${weaponNumber(i,'Extra ammunition rounds','ammo',0)}${weaponSelect(i,'Reserve ammunition type','ammoType',F.ammunition.map(a=>a.name))}${weaponNumber(i,'Gun shield Protection (p103)','gunShield',0)}${weaponNumber(i,'Assigned loaders (without autoloader)','loaders',0)}<div class="wide scope-notice">Reserve ammunition: ${esc(F.ammunition.find(a=>a.name===(w.ammoType||'Standard'))?.effect||'')}. Special ammunition affects purchased reloads only. Base weapon statistics remain listed; calibre and compatibility need review. ${bh('120–123')}</div><div>${weaponCheck(i,'Remote gunner','remote')}${weaponCheck(i,'Autoloader · TL6+','autoloader')}${weaponCheck(i,'Pop-up mount','popup')}${weaponCheck(i,'Modular mount','modular')}</div></div><div class="statchips"><span>${fmt(result.weaponResults[i]?.spaces)} Spaces</span><span>${money(result.weaponResults[i]?.cost)}</span><span>${esc(result.weaponResults[i]?.damage)} damage</span></div>${ref(F.weapons.find(x=>x.Weapon===w.weapon))}${bh('101–105 (mounts, loading and fire control)')}</div></div>`).join('')+(state.weapons.length?'':'<div class="empty">No weapon mounts. This vehicle is unarmed.</div>');},
crew(){return panel('10','Occupants & accommodation',`<div class="body"><div class="grid">${field('Crew','crew','number','min="0" step="1"')}${field('Main group passengers','passengers','number','min="0" step="1"')}${field('Crew Spaces per person','crewSpace','number','min="0.25" max="100" step="0.25"')}${field('Main group Spaces per person','passengerSpace','number','min="0.25" max="100" step="0.25"')}${select('Sophont size multiplier','sophont',[[.5,'0.5 · Small sophont'],[1,'1 · Human / Aslan / Vargr'],[2,'2 · 251–500 kg'],[3,'3 · Dolphin'],[4,'4 · Virushi'],[5,"5 · K’kree"],[12,'12 · Orca']])}${check('Remotely operated drone','drone')}</div>${rule('One Space per human-sized occupant is standard. Smaller seating allocations reduce comfort. Each accommodation group rounds up; fractions never create partial installed Spaces.','24–27')}<div class="statchips"><span>Crew <b>${comfortName(state.crewSpace)}</b></span><span>Main passenger seating <b>${comfortName(state.passengerSpace)}</b></span></div>${passengerGroupEditor()}${comfortSummary()}</div>`)+panel('↳','Cargo & description',`<div class="body"><div class="grid">${field('Cargo Spaces','cargo','number','min="0" step="1"',`${fmt(state.cargo*250)} kg nominal cargo capacity`)}<div><label>Unallocated capacity</label><div class="statchips"><span><b>${fmt(result.remaining)}</b> Spaces</span></div></div><label class="field wide">Design notes<textarea rows="4" data-key="description" maxlength="5000">${esc(state.description)}</textarea></label></div>${rule('Cargo fittings and basic occupant Spaces are included in the chassis cost. Cargo is 250 kg or one-quarter displacement ton per Space.','27')}</div>`);},
record(){return vehicleSheet()+`<details class="panel no-print build-details"><summary>Construction checks & cost ledger</summary><div class="body">${issuesHTML()}${result.notes.map(n=>`<div class="note">${esc(n)}</div>`).join('')}<p class="muted">“Passed” refers to implemented checks. Specialist rules requiring review are flagged above.</p></div>${ledgerTable()}</details>`;}

};
function signed(n){return n>=0?'+'+fmt(n):fmt(n)}function roundPercent(n){return Math.round(n*100)}
function passengerGroupEditor(){return `<h3>Additional passenger seating</h3><p class="muted">Add a group for each different seat size. Include the driver under Crew, not Passengers. Fold-down seats reserve their occupied space; no automatic cargo-space credit is applied when folded.</p>${state.passengerGroups.map((g,i)=>`<div class="panel"><div class="body"><div class="grid"><label class="field">Group label<input data-passenger-group="${i}" data-prop="name" maxlength="100" value="${esc(g.name)}"></label><label class="field">Passengers<input type="number" min="0" max="1000000" step="1" data-passenger-group="${i}" data-prop="count" value="${esc(g.count)}"></label><label class="field">Spaces per person<input type="number" min="0.25" max="100" step="0.25" data-passenger-group="${i}" data-prop="space" value="${esc(g.space)}"></label></div><p>Seating comfort: ${comfortName(g.space)} · ${fmt(g.space)} per person</p><button class="small danger" data-remove-passenger-group="${i}">Remove group</button></div></div>`).join('')}<button data-action="add-passenger-group" ${state.passengerGroups.length>=100?'disabled':''}>Add passenger group</button><p>${fmt(result.passengerCount)} passengers + ${fmt(state.crew)} crew · ${fmt(result.passengerSpaces+result.crewSpaces)} accommodation Spaces</p>`;}
function comfortSummary(){return `<div class="rule"><strong>Overall comfort: ${result.comfort===null?'No occupants':comfortName(result.comfort)+' · '+fmt(result.comfort)+' CP/person'}</strong><br>Equipment contribution: ${fmt(result.comfortBonus)} Comfort Points total, shared across occupants. Seating labels describe the seat allocation only. Each group's installed Spaces round up.${bh('24–27, 83–85, 100')}</div>`;}
function comfortName(v){return [...D.ComfortLevel].reverse().find(x=>v>=x['Starts at'])?.['Comfort Level']||'Intolerable'}
function equipmentTable(readonly=false){return state.equipment.length?`<div class="tablewrap"><table><thead><tr><th>Equipment / book & page</th><th>Qty</th><th>Spaces</th><th>Cost</th><th class="no-print"></th></tr></thead><tbody>${state.equipment.map((e,i)=>{const o=F.options.find(x=>x.Name===e.name),v=F.optionBudget(o,e.quantity,state,e);if(o._robotArm)v.spaces='pooled';return `<tr><td>${esc(e.name)}<small class="equipment-detail">${esc(equipmentDetail(o,e))}</small>${ref(o)}</td><td>${readonly?esc(e.quantity):`<input type="number" min="1" step="1" class="tableinput no-print" aria-label="${esc(U.quantityLabel(o))} of ${esc(e.name)}" value="${e.quantity}" data-option-qty="${i}"><span class="print-only">${e.quantity}</span>`}<small class="quantity-unit">${esc(U.quantityLabel(o))}</small></td><td>${v.spaces}</td><td>${money(v.cost)}</td><td class="no-print">${readonly?'':`<button class="small danger" data-remove-option="${i}" aria-label="Remove ${esc(e.name)}">×</button>`}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="body"><div class="empty">No optional equipment installed.</div></div>'}
function ledgerTable(){return `<div class="tablewrap"><table><thead><tr><th>Component</th><th>Spaces*</th><th>Cost</th><th>Book & page</th></tr></thead><tbody>${result.ledger.filter(x=>x.spaces||x.cost).map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.spaces)}</td><td>${money(x.cost)}</td><td>${ref(x.source)}</td></tr>`).join('')}<tr><td><strong>Total cost</strong></td><td>${result.used} used</td><td><strong>${money(result.total)}</strong></td><td>${bh('25–27')}</td></tr></tbody></table><p class="muted" style="padding:12px 16px">* Negative entries increase usable capacity. Base capacity ${state.type==='Structure'?state.spaces*2:state.spaces}; final capacity ${result.capacity} Spaces.</p></div>`}
function issuesHTML(){return result.issues.length?result.issues.map(x=>`<div class="issue ${x.level}"><b>${x.level==='review'?'REVIEW':'FIX REQUIRED'} · ${esc(x.code)}</b>${esc(x.message)}<small>Vehicle Handbook Update 2026 · p. ${x.page}</small></div>`).join(''):'<div class="rule">All implemented construction checks pass. No unresolved equipment review flags.</div>'}
function renderSummary(){const errors=result.issues.filter(x=>x.level==='error').length,reviews=result.issues.length-errors;$('#summary').innerHTML=`<div class="summarytop"><span class="eyebrow">LIVE BUILD SUMMARY</span><div class="price"><span>Cr</span> ${fmt(result.total)}</div><div class="status ${errors?'bad':reviews?'review':''}">${errors?'! '+errors+' construction issue'+(errors>1?'s':''):reviews?'△ '+reviews+' item'+(reviews>1?'s':'')+' need review':'✓ Construction checks passed'}</div></div><div class="summarybody"><div class="spaced"><label>Usable capacity</label><span class="muted">${fmt(result.used)} / ${fmt(result.capacity)}</span></div><div class="meter"><span style="width:${Math.max(0,Math.min(100,result.used/Math.max(1,result.capacity)*100))}%;${result.remaining<0?'background:var(--red)':''}"></span></div><div class="spaced"><span class="capacityvalue" style="${result.remaining<0?'color:var(--red)':''}">${fmt(result.remaining)}</span><small class="muted">Spaces remaining</small></div><div class="metrics"><div class="metric"><small>MAX SPEED</small><b>${band(result.speed)}</b><em>${band(result.cruise)} cruise</em></div><div class="metric"><small>RANGE</small><b>${result.infinite?'—':fmt(result.range)+' km'}</b><em>${result.infinite?'Source-dependent':fmt(result.cruiseRange)+' km cruise'}</em></div><div class="metric"><small>HULL</small><b>${fmt(result.hull)}</b><em>Total hull value</em></div><div class="metric"><small>STRUCTURE</small><b>${fmt(result.structure)}</b><em>Hull ÷ 10, rounded up · p6</em></div><div class="metric"><small>AGILITY</small><b>${signed(result.agility)}</b><em>${fmt(result.shipping)} shipping tons</em></div></div>${result.traits.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}<button class="summarybutton" data-tab="record">View full record & ledger →</button><button class="summarybutton" data-action="local-save">Save in this browser</button><button class="summarybutton" data-action="local-load">Restore browser save</button>${bh('25–56')}</div>${result.issues.length?`<div class="issues">${result.issues.slice(0,4).map(x=>`<div class="issue ${x.level}">${esc(x.message)}<small>Vehicle Handbook Update 2026 · p. ${x.page}</small></div>`).join('')}${result.issues.length>4?`<button data-tab="record">View all ${result.issues.length} checks</button>`:''}</div>`:''}`;}
function weaponSelect(i,label,prop,values){return `<label class="field">${label}<select data-weapon="${i}" data-prop="${prop}">${values.map(v=>`<option ${(state.weapons[i][prop]||(prop==='ammoType'?'Standard':''))===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function weaponNumber(i,label,prop,min){return `<label class="field">${label}<input type="number" min="${min}" step="1" data-weapon="${i}" data-prop="${prop}" value="${state.weapons[i][prop]??(prop==='loaders'?Number(F.weapons.find(w=>w.Weapon===state.weapons[i].weapon)?.Loader||0)*state.weapons[i].quantity:0)}"></label>`}
function weaponCheck(i,label,prop){return `<label class="inline"><input type="checkbox" data-weapon="${i}" data-prop="${prop}" ${state.weapons[i][prop]?'checked':''}>${label}</label>`}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function sources(){ $('#source-content').innerHTML=`<p><strong>Primary authority:</strong> <em>Traveller — The Vehicle Handbook Update 2026</em>, supplied PDF dated 01-04-2026. All page numbers here are the printed book pages; the PDF viewer page is one higher.</p><p><strong>Data source:</strong> <em>VehicleDesignWorksheet-v056Blank.xlsx</em>, version 0.56. Table rows preserve sheet and cell references. Catalog section citations locate the relevant discussion; numeric values originate in the worksheet unless a correction is listed below.</p><h3>Automated rule coverage</h3><div class="tablewrap"><table><thead><tr><th>Area</th><th>Checks</th><th>Book & pages</th></tr></thead><tbody>${F.rules.map(([n,p,r])=>`<tr><td>${n}</td><td>${esc(r)}</td><td>${bh(p)}</td></tr>`).join('')}</tbody></table></div><h3>Source differences & explicit rulings</h3><div class="tablewrap"><table><thead><tr><th>Rule</th><th>Ruling</th><th>Source references</th></tr></thead><tbody>${F.corrections.map(([n,c,p,r])=>`<tr><td>${esc(n)}</td><td>${esc(r)}</td><td>${bh(p)}<span class="ref">Vehicle Design Worksheet v0.56 · ${esc(c)}</span></td></tr>`).join('')}</tbody></table></div>${auditHTML()}<h3>Pages 127–130: modifications to existing vehicles</h3><p>These pages cover refit labour, compatibility checks, replacing features and unsafe tuning. This workbench prices new construction; it does not apply refit surcharges, salvage values or mechanic checks. Biological construction (pp131–136) is omitted.</p><h3>Limits of verification</h3><p>Numeric table extraction is not proof that every optional system’s prose rules have been automated. Specialist entries, certain combined systems and multi-computer program allocation raise review flags. Biotech, refits, custom robotics, spacecraft subsystem design and combat resolution are outside the automated scope. No invalid or review-required design is labelled as fully checked.</p><p>Full source PDFs and workbook remain in your local project. They are not embedded in this site.</p>`;$('#source-dialog').showModal();}
document.addEventListener('change',e=>{
 const el=e.target,d=el.dataset;
 if(d.key){state[d.key]=el.type==='checkbox'?el.checked:typeof F.defaults[d.key]==='number'?Number(el.value):el.value;}
 else if(d.passengerGroup!==undefined){state.passengerGroups[+d.passengerGroup][d.prop]=d.prop==='name'?el.value:Number(el.value);}
 else if(d.systemQty!==undefined){systemQuantities[d.systemQty]=Math.max(1,Math.min(1000000,Math.floor(Number(el.value)||1)));el.closest('.system-card').outerHTML=systemCard(systemGroups[+d.systemQty]);return;}
 else if(d.systemConfig!==undefined){const cfg=systemConfigs[d.systemConfig]||(systemConfigs[d.systemConfig]={});cfg[d.prop]=el.type==='checkbox'?el.checked:Number(el.value);el.closest('.system-card').outerHTML=systemCard(systemGroups[+d.systemConfig]);return;}
 else if(d.system!==undefined){systemPicks[d.system]=el.value;const card=el.closest('.system-card');card.outerHTML=systemCard(systemGroups[+d.system]);return;}
 else if(d.feature){state.features=el.checked?[...state.features,d.feature]:state.features.filter(x=>x!==d.feature);}
 else if(d.armour!==undefined)state.armourShift[+d.armour]=Number(el.value);
 else if(d.aux!==undefined){state.aux[+d.aux]=el.value;state.aux=state.aux.filter(x=>x&&x!=='none');}
 else if(d.optionQty!==undefined)state.equipment[+d.optionQty].quantity=Number(el.value);
 else if(d.weapon!==undefined)state.weapons[+d.weapon][d.prop]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;
 else if(el.id==='equipment-group')group=el.value;else return;
 render();
});
$('#vehicle-name').addEventListener('input',e=>state.name=e.target.value);
document.addEventListener('input',e=>{if(e.target.id==='equipment-search'){const pos=e.target.selectionStart;filter=e.target.value;$('#editor').innerHTML=views.equipment();const input=$('#equipment-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el)return;const d=el.dataset;
 if(d.tab){tab=d.tab;filter='';group='All';render();window.scrollTo({top:0});return;}
 if(d.action==='add-passenger-group'){if(state.passengerGroups.length<100)state.passengerGroups.push({name:'Additional seats',count:0,space:1});render();return;}
 if(d.removePassengerGroup!==undefined){state.passengerGroups.splice(+d.removePassengerGroup,1);render();return;}
 if(d.removeFeature){state.features=state.features.filter(x=>x!==d.removeFeature);render();return;}
 if(d.equipmentSearch!==undefined){filter=d.equipmentSearch;group='All';if(!filter)filter=' ';render();return;}
 if(d.installSystem!==undefined){const g=systemGroups[+d.installSystem],o=g.options.find(x=>x.Name===systemPicks[d.installSystem]&&x.TL<=state.tl)||g.options.find(x=>x.TL<=state.tl);if(!o)return;const cfg=(o.Name.startsWith('Sensor System')||o._robotArm||/^(Heavy )?Manipulator Arm \(/.test(o.Name))?{...(systemConfigs[d.installSystem]||{})}:{},quantity=systemQuantities[d.installSystem]||defaultSystemQuantity(o);const keys=['highFidelity','hardened','mast','rangeBoost','armSize','strIncrease','dexIncrease'];const existing=state.equipment.find(e=>e.name===o.Name&&keys.every(k=>(e[k]||0)===(cfg[k]||0)));if(existing)existing.quantity+=quantity;else state.equipment.push({name:o.Name,quantity,...cfg});render();toast('Equipment installed');return;}
 if(d.addOption){const exists=state.equipment.find(x=>x.name===d.addOption);if(exists)exists.quantity++;else state.equipment.push({name:d.addOption,quantity:1});render();toast('Equipment added');return;}
 if(d.removeOption!==undefined){state.equipment.splice(+d.removeOption,1);render();return;}
 if(d.removeWeapon!==undefined){state.weapons.splice(+d.removeWeapon,1);render();return;}
 if(d.preset){state=presets(d.preset);render();toast('Starting design loaded');return;}
 if(d.action==='sources')sources();
 if(d.action==='close-sources')$('#source-dialog').close();
 if(d.action==='save'){const payload={...state,version:state.passengerGroups.length?2:1};download(JSON.stringify(payload,null,2),(state.name||'vehicle').replace(/[^a-z0-9_-]/gi,'-')+'.json','application/json');}
 if(d.action==='load')$('#file-input').click();
 if(d.action==='local-save'){try{localStorage.setItem('traveller-forge-design',JSON.stringify(state));toast('Saved in this browser');}catch{toast('Browser storage unavailable. Use Save JSON.');}}
 if(d.action==='local-load'){try{const saved=localStorage.getItem('traveller-forge-design');if(!saved){toast('No browser save yet');return}state=validateImport(JSON.parse(saved));render();toast('Design restored');}catch(err){toast('Could not restore: '+err.message);}}
 if(d.action==='print'){tab='record';render();window.print();}
 if(d.action==='add-weapon'){const w=F.weapons.find(x=>x.Weapon==='Machinegun (medium)'&&x.TL<=state.tl)||F.weapons.find(x=>x.TL<=state.tl)||F.weapons[0];state.weapons.push({weapon:w.Weapon,mount:'Fixed Mount',facing:'Forward',quantity:1,fireControl:'none',remote:false,autoloader:false,popup:false,modular:false,ammo:0,ammoType:'Standard',gunShield:0});render();}
});
function download(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validateImport(raw){
 if(!raw||![1,2].includes(raw.version)||typeof raw!=='object')throw Error('Unsupported design format');
 const s=structuredClone(F.defaults);
 for(const key of Object.keys(s))if(Object.hasOwn(raw,key)){
  const v=raw[key];if(Array.isArray(s[key])){if(!Array.isArray(v)||v.length>500)throw Error('Invalid '+key);s[key]=v;}
  else if(typeof v!==typeof s[key]||typeof v==='number'&&!Number.isFinite(v)||typeof v==='string'&&v.length>5000)throw Error('Invalid '+key);else s[key]=v;
 }
 if(s.passengerGroups.length>100||!s.passengerGroups.every(F.validPassengerGroup))throw Error('Invalid passenger seating group');
 if(!F.types.some(x=>x.Type===s.type)||!F.powers.some(x=>x.Power===s.power)||(s.secondary!=='none'&&!F.powers.some(x=>x.Power===s.secondary)))throw Error('Unknown chassis or power');
 if(!s.features.every(x=>typeof x==='string')||!s.aux.every(x=>typeof x==='string')||s.armourShift.length!==6||!s.armourShift.every(Number.isFinite))throw Error('Invalid feature or armour data');
 if(!s.equipment.every(x=>x&&F.options.some(o=>o.Name===x.name)&&Number.isInteger(x.quantity)&&x.quantity>0))throw Error('Unknown equipment or invalid quantity');
 for(const e of s.equipment){for(const k of ['armSize','strIncrease','dexIncrease'])if(e[k]!==undefined&&(!Number.isInteger(e[k])||e[k]<0))throw Error('Invalid manipulator characteristic');for(const k of ['highFidelity','hardened','mast'])if(e[k]!==undefined&&typeof e[k]!=='boolean')throw Error('Invalid sensor customisation');if(e.rangeBoost!==undefined&&(!Number.isInteger(e.rangeBoost)||e.rangeBoost<0||e.rangeBoost>3))throw Error('Invalid sensor range');}
 if(!s.unmodelledComponents.every(x=>typeof x==='string'&&x.length<=5000))throw Error('Invalid unresolved-component notes');
 if(!s.weapons.every(x=>x&&F.weapons.some(w=>w.Weapon===x.weapon)&&Number.isInteger(x.quantity)&&x.quantity>0&&typeof x.mount==='string'))throw Error('Unknown weapon or invalid mount');
 return s;
}
$('#file-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('File exceeds 1 MB');state=validateImport(JSON.parse(await f.text()));render();toast('Design opened');}catch(err){toast('Could not open: '+err.message);}e.target.value='';});
function presets(id){const s=structuredClone(F.defaults);if(id==='blank')return {...s,name:'Untitled vehicle',features:[],passengers:0,cargo:0};if(id==='raft')return {...s,name:'Survey air/raft',type:'Grav Vehicle',tl:12,spaces:8,features:['Open-Topped'],crew:1,passengers:3,cargo:4};return s;}
// Progressive WebMCP: the same validated state and calculation engine powers agent actions.
const toolContext=document.modelContext;
if(toolContext?.registerTool){
 const lifecycle=new AbortController();
 const register=tool=>{try{Promise.resolve(toolContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'inspect_vehicle_design',title:'Inspect vehicle design',description:'Read the current draft and explicit construction checks.',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({design:state,checks:result.issues,cost:result.total,remainingSpaces:result.remaining})});
 register({name:'load_vehicle_design',title:'Load vehicle draft',description:'Replace the visible draft with a version 1 or 2 design and run construction checks. This does not save or publish it.',annotations:{readOnlyHint:false},inputSchema:{type:'object',properties:{design:{type:'object'}},required:['design'],additionalProperties:false},execute:async({design})=>{const next=validateImport(design);state=next;render();return {valid:result.valid,review:result.review,checks:result.issues,cost:result.total};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
render();

function weaponRecord(){
 if(!result.weaponResults.length)return '';
 return panel('≡','Armament record',`<div class="tablewrap"><table><thead><tr><th>Mount & weapon</th><th>Base range / damage</th><th>Traits</th><th>Book & page</th></tr></thead><tbody>${result.weaponResults.map(w=>`<tr><td>${esc(w.facing)} ${esc(w.mount)}<br>${esc(w.weapon)} × ${w.quantity}</td><td>${fmt(w.range)} km / ${esc(w.damage)}${w.quantity>1?'<br>Linked damage: +1 per die per extra weapon (before Destructive multiplier).':''}</td><td>${esc(w.traits)}<br>Fire control: ${esc(w.fireControl)}${w.gunShield?`<br>Gun shield: ${w.gunShield}`:''}${w.ammoType&&w.ammoType!=='Standard'?`<br>Reserve: ${esc(w.ammoType)} · ${fmt(w.ammo)} rounds<br>${esc(w.ammoEffect)}${bh('120–123')}`:''}</td><td>${ref(F.weapons.find(x=>x.Weapon===w.weapon))}${bh('101–105')}</td></tr>`).join('')}</tbody></table></div>`);
}
function auxRecord(){
 if(!result.auxResults.length)return '';
 return panel('≡','Auxiliary drives',`<div class="tablewrap"><table><thead><tr><th>Drive</th><th>Speed / agility</th><th>Range</th><th>Book & page</th></tr></thead><tbody>${result.auxResults.map(a=>`<tr><td>${esc(a.name)}</td><td>${band(a.speed)} / ${signed(a.agility)}</td><td>${fmt(a.range)} km</td><td>${ref(D.Secondary.find(x=>x.Secondary===a.name))}</td></tr>`).join('')}</tbody></table></div>`);
}
function defaultSystemQuantity(o){return /^Life Support \(/.test(o.Name)?Math.max(1,state.crew+result.passengerCount):o.Name==='Tow Hitch'?state.spaces:1;}
function equipmentDetail(o,e){if(!o)return '';const v=F.optionBudget(o,e.quantity,state,e);if(o._robotArm)return `Size ${e.armSize??5} · STR ${v.str} · DEX ${v.dex}. Arm Spaces pooled in ledger (Vehicle Handbook p67).`;if(/^(Heavy )?Manipulator Arm \(/.test(o.Name))return `STR +${e.strIncrease||0} · DEX +${e.dexIncrease||0} · ${o.Traits||''}`;if(o.Name.startsWith('Sensor System'))return [fmt(v.range)+' km',e.highFidelity?'High fidelity (+1 DM)':'',e.hardened?'Hardened (ignores DM−1 jamming)':'',e.mast?'Sensor mast':''].filter(Boolean).join(' · ');if(o.Name==='Tow Hitch')return `Includes cables & hooks; rated for ${e.quantity} powered or ${e.quantity*2} unpowered towed Spaces.`;if(o.Name==='Winch')return '25-metre cable; one winch per face.';if(o.Name==='Docking Bay'||o.Name==='Hangar Bay')return `${fmt(v.spaces/(o.Name==='Docking Bay'?4.4:8))} shipping tons capacity; check vehicle shape and fit.`;if(/^Life Support \(/.test(o.Name))return `${v.spaces*(o.Name.includes('short')?20:5)} people capacity · ${o.Name.includes('short')?'4 days':o.Name.includes('long')?'90 days':'indefinite with routine maintenance'}`;return String(o.Traits||'');}
function systemCard(g){
 const id=systemGroups.indexOf(g),eligible=g.options.filter(o=>o.TL<=state.tl),picked=g.options.find(o=>o.Name===systemPicks[id]&&o.TL<=state.tl),o=picked||eligible[0],cfg=systemConfigs[id]||{},q=systemQuantities[id]||(o?defaultSystemQuantity(o):1),v=o?F.optionBudget(o,q,state,cfg):null;
 const installed=state.equipment.filter(e=>g.options.some(o=>o.Name===e.name));
 return `<section class="system-card"><label class="field">${esc(g.name)}<select data-system="${id}" ${!o?'disabled':''} aria-label="${esc(g.name)} option">${eligible.map(x=>`<option value="${esc(x.Name)}" ${x===o?'selected':''}>${esc(x.Name)} · TL${x.TL}+</option>`).join('')||'<option>No option at this TL</option>'}</select></label><p class="system-note">${o?esc(systemNote(g.name,o)):`Available from TL${Math.min(...g.options.map(x=>x.TL))}.`}</p>${o?`${(o._robotArm||/^(Heavy )?Manipulator Arm \(/.test(o.Name))?`<fieldset class="sensor-custom"><legend>Manipulator characteristics · p67</legend>${(o._robotArm?[['armSize','Robot Size',5],['strIncrease','STR increase',0],['dexIncrease','DEX increase',0]]:[['strIncrease','STR increase',0],['dexIncrease','DEX increase',0]]).map(([key,label,value])=>`<label>${label}<input type="number" min="${key==='armSize'?1:0}" step="1" data-system-config="${id}" data-prop="${key}" value="${cfg[key]??value}"></label>`).join('')}<small>Robot arm sizes and characteristic limits are checked when installed. Vehicle arm increases total at most +5.</small></fieldset>`:''}${o.Name.startsWith('Sensor System')?`<fieldset class="sensor-custom"><legend>Sensor customisations · p60</legend>${[['highFidelity','High fidelity · TL6',6],['hardened','Hardened · TL7',7],['mast','Sensor mast',0]].map(([key,label,tl])=>`<label class="inline"><input type="checkbox" data-system-config="${id}" data-prop="${key}" ${cfg[key]?'checked':''} ${state.tl<tl?'disabled':''}>${label}</label>`).join('')}<label>Range multiplier<select data-system-config="${id}" data-prop="rangeBoost">${[0,1,2,3].map(n=>`<option value="${n}" ${(cfg.rangeBoost||0)===n?'selected':''}>×${10**n}</option>`).join('')}</select></label><small>Effective range: ${fmt(v.range)} km</small></fieldset>`:''}<label class="quantity-picker">${esc(U.quantityLabel(o))}<input aria-label="${esc(g.name)} ${esc(U.quantityLabel(o))}" type="number" min="1" max="1000000" step="1" data-system-qty="${id}" value="${q}"></label><div class="system-budget"><span>${fmt(v.spaces)} Spaces</span><strong>${money(v.cost)}</strong><button class="small" data-install-system="${id}" aria-label="Install ${esc(o.Name)}">Install</button></div>${ref(o)}`:''}${installed.length?`<p class="installed-note">Installed: ${installed.map(e=>`${esc(e.name)} × ${e.quantity}`).join('; ')}</p>`:''}</section>`;
}
function systemNote(f,o){
 const notes={'Tow Hitch':'Includes tow cables and hooks. Enter the powered vehicle Spaces to be towed; twice that capacity applies to unpowered loads.','Winch':'Includes a 25-metre cable. Pulling requires power; one per vehicle face.','Transceiver Encryption':'Government-grade end-to-end encryption. Each communicating party needs a compatible module. Cost stays Cr4000 at higher TLs.','Transceiver Tightbeam':'Laser or maser point-to-point mode; requires line of sight and is difficult to intercept.','Satellite Uplink':'Tracks orbiting satellites or spacecraft. Requires a radio with at least 500 km range. Uses no Spaces from TL8.','Docking Bay':'Allocate ceil(4.4 × carried vehicle shipping tons) Spaces. The compartment fits a specific vehicle shape.','Hangar Bay':'Allocate ceil(8 × carried vehicle shipping tons) Spaces, including maintenance and deployment room.','Digger Blade':'Quantity is blade Spaces; maximum 25% of the vehicle’s nominal Spaces.','Landing Deck':'Quantity is the largest aircraft’s nominal Spaces. Each needs ten deck Spaces.','Launch Deck':'Quantity is the largest aircraft’s nominal Spaces. Each needs ten deck Spaces.',Autopilot:'Automates vehicle operation; higher grades improve piloting capability.',Transceiver:'Two-way radio; choose the required communications range.', 'Meson Communicator':'Communication using mesons; choose the required range.', 'Navigation System':'Assists navigation and route finding.', 'Sensor System':'Detects and tracks targets in the surrounding environment.', 'Underwater sensors':'Sensors adapted for underwater use, with reduced range.', Computer:'Runs installed software within its bandwidth limit.', 'Life Support':'Quantity represents people supported. Requires suitable hull sealing.', ECM:'Electronic countermeasures for protection against sensors and targeting.',Camouflage:'Reduces visual detection. Check compatibility with other hull treatments.',Stealth:'Reduces the vehicle’s sensor signature.'};
 const trait=o.Traits!==null&&o.Traits!==undefined&&o.Traits!==''?String(o.Traits):'';
 return [notes[f]||'Select a specification and install the quantity your design needs.',trait?(f==='Sensor System'?`Range: ${trait} km.`:`Specification: ${trait}.`):'',o.Powered==='P'?'Requires power.':'',F.category(o)==='Specialist & spacecraft'?'Specialist rules require review.':''].filter(Boolean).join(' ');
}
function vehicleSheet(){
 const status=result.valid?(result.review?'REVIEW REQUIRED':'CONSTRUCTION CHECKS PASSED'):'INVALID DRAFT';
 const stats=[['TL',state.tl],['Hull',fmt(result.hull)],['Structure',fmt(result.structure)],['Agility',signed(result.agility)],['Cost',money(result.total)]];
 const profile=[['Speed',`${band(result.speed)} (${band(result.cruise)} cruise)`],['Range',result.infinite?'Source-dependent endurance':`${fmt(result.range)} km (${fmt(result.cruiseRange)} km cruise)`],['Power',state.power+(state.secondary!=='none'?` + ${state.secondary}`:'')],['Skill',result.t.Skill],['Crew',`${state.crew} · ${comfortName(state.crewSpace)}`],['Passengers',`${result.passengerCount} · `+result.passengerSeating.filter(g=>g.count).map(g=>`${g.name}: ${g.count} × ${fmt(g.space)} Spaces (${comfortName(g.space)})`).join(';')],['Equipment comfort bonus',fmt(result.comfortBonus)+' CP total'],['Overall comfort',result.comfort===null?'No occupants':comfortName(result.comfort)+' · '+fmt(result.comfort)+' CP/person'],['Cargo',`${state.cargo} Spaces / ${fmt(state.cargo*250)} kg`],['Shipping',`${fmt(result.shipping)} tons`],['Capacity',`${result.used} / ${result.capacity} Spaces used`],['Power output / load',`${fmt(result.pp)} / ${fmt(result.powerDemand)}`]];
 return `<article class="vehicle-sheet"><header class="vehicle-sheet-header"><div><span class="sheet-kicker">TRAVELLER / VEHICLE RECORD</span><h1>${esc(state.name||'Unnamed vehicle')}</h1><p>${esc(result.size['Size Name'])} ${esc(state.type)} · ${fmt(state.spaces)} nominal Spaces</p></div><span class="sheet-status ${result.valid&&!result.review?'':'attention'}">${status}</span></header><div class="sheet-stats">${stats.map(([label,value])=>`<div><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div><p class="sheet-reference">Hull is the construction value. Structure is the damage threshold: Hull ÷ 10, rounded up. Some Vehicle Catalogue entries print Hull under the Structure heading; do not use that larger number as the threshold. ${bh('6 (Hull and Structure); 25–56 (construction)')}</p><section class="sheet-section"><h2>Performance & accommodation</h2><dl class="sheet-profile">${profile.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section><section class="sheet-section"><h2>Protection</h2><div class="tablewrap"><table class="protection-table"><thead><tr><th>Armour</th>${F.faces.map(f=>`<th>${f}</th>`).join('')}<th>Book & page</th></tr></thead><tbody><tr><th>Vehicle-scale</th>${result.protection.map(p=>`<td>${p}</td>`).join('')}<td rowspan="2">${bh('55–56')}</td></tr><tr><th>Small arms</th>${result.protection.map(p=>`<td>${p+(p>=result.baseArmour?state.tl:0)}</td>`).join('')}</tr></tbody></table></div></section><section class="sheet-section"><h2>Features & traits</h2><p>${[...new Set([...result.traits,...state.features])].map(t=>`<span class="chip">${esc(t)}</span>`).join('')||'None'}${bh('35–43')}</p></section><section class="sheet-section"><h2>Weapons</h2>${result.weaponResults.length?weaponRecord():'<p class="muted">Unarmed</p>'}</section><section class="sheet-section"><h2>Systems & equipment</h2><p class="sheet-control">${esc(state.control)} × ${state.controlQuantity||1}${ref(F.options.find(o=>o.Name===state.control))}</p>${equipmentTable(true)}</section>${result.auxResults.length?`<section class="sheet-section"><h2>Auxiliary locomotion</h2>${auxRecord()}</section>`:''}${state.description?`<section class="sheet-section"><h2>Notes</h2><p class="design-notes">${esc(state.description)}</p></section>`:''}${result.notes.length?`<section class="sheet-section"><h2>Operational notes</h2>${result.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</section>`:''}${result.issues.length?`<section class="sheet-section sheet-checks"><h2>Outstanding construction checks</h2>${issuesHTML()}</section>`:''}<footer class="sheet-footer">Vehicle Handbook Update 2026 · Automated checks cover implemented construction rules.<button class="no-print small" data-action="sources">Book & worksheet sources</button></footer></article>`;
}


function auditHTML(){
 const a=globalThis.EQUIPMENT_AUDIT;if(!a)return '';
 const skipped=[...new Map(a.rows.filter(x=>x.status!=='Included').map(x=>[x.name,x])).values()];
 return `<h3>Equipment coverage audit</h3><p>All ${a.counts.worksheetOptions} worksheet option rows and ${a.counts.worksheetWeapons} weapon rows are accounted for. ${a.counts.includedOptions} option rows and ${a.counts.includedWeapons} non-biological weapon rows are selectable. Headings, placeholders and items without complete construction data remain listed below. This coverage check does not certify every operating or combination rule.</p><div class="tablewrap"><table><thead><tr><th>Section</th><th>Coverage</th><th>Book & page</th></tr></thead><tbody>${a.coverage.map(([pages,name,coverage])=>`<tr><td>${esc(name)}</td><td>${esc(coverage)}</td><td>${bh(pages)}</td></tr>`).join('')}</tbody></table></div><details><summary>Worksheet rows requiring manual specifications or represented elsewhere</summary><div class="tablewrap"><table><thead><tr><th>Worksheet entry</th><th>Reason</th><th>Source</th></tr></thead><tbody>${skipped.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.notes)}</td><td><span class="ref">Vehicle Design Worksheet v0.56 · ${esc(r.source)}</span></td></tr>`).join('')}</tbody></table></div></details>`;
}

